List<int> noten = new List<int> { 2, 1, 4, 3 };
noten[2] = 3;          // Element an Index 2 ersetzen
noten.Insert(0, 5);    // an Index 0 einfügen, Rest rutscht nach hinten

foreach (int n in noten)
{
    Console.Write(n + " ");
}
// Ausgabe: 5 2 1 3 3

var namen = new List<string> { "Lena", "Ali", "Mia", "Ali" };
namen.Remove("Ali");      // nur das ERSTE "Ali" verschwindet
namen.RemoveAt(0);        // "Lena" verschwindet

Console.WriteLine(string.Join(", ", namen));
Console.WriteLine(namen.Contains("Mia"));
Console.WriteLine(namen.IndexOf("Tom"));
// Ausgabe:
// Mia, Ali
// True
// -1

var punkte = new List<int> { 40, 15, 80, 15 };
punkte.Sort();
Console.WriteLine(string.Join(" ", punkte));
punkte.Reverse();
Console.WriteLine(string.Join(" ", punkte));
// Ausgabe:
// 15 15 40 80
// 80 40 15 15

var zahlen = new List<int> { 3, 8, 5, 10, 7 };
// alle geraden Zahlen entfernen – von hinten nach vorne!
for (int i = zahlen.Count - 1; i >= 0; i--)
{
    if (zahlen[i] % 2 == 0)
    {
        zahlen.RemoveAt(i);
    }
}
Console.WriteLine(string.Join(" ", zahlen));
// Ausgabe: 3 5 7

